@push('scripts')
<script>
(function(){const video=document.getElementById('employee-face-video'),canvas=document.getElementById('employee-face-canvas'),button=document.getElementById('employee-face-submit'),status=document.getElementById('employee-face-status');const endpoint=@json($presensiStoreUrl),redirectUrl=@json($presensiUrl),csrf=@json(csrf_token()),mode=@json($mode);let stream=null,busy=false;function setStatus(t){status.textContent=t}async function init(){try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:720},height:{ideal:900}},audio:false});video.srcObject=stream;await video.play();button.disabled=false;setStatus('Kamera siap. Posisikan wajah di dalam garis.')}catch(e){setStatus('Kamera tidak dapat diakses. Izinkan kamera lalu muat ulang halaman.')}}function frame(){const w=video.videoWidth||720,h=video.videoHeight||900,tw=Math.min(w,720),th=Math.round(tw*h/w);canvas.width=tw;canvas.height=th;canvas.getContext('2d').drawImage(video,0,0,tw,th);return canvas.toDataURL('image/jpeg',.82)}async function scan(){if(busy)return;busy=true;button.disabled=true;setStatus('Memeriksa wajah...');try{const frames=[];for(let i=0;i<5;i++){frames.push(frame());if(i<4)await new Promise(r=>setTimeout(r,180))}const res=await fetch(endpoint,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf,'X-Requested-With':'XMLHttpRequest'},body:JSON.stringify({face_engine:'python',face_frames:frames,selfie_data:frames[4],presensi_mode:mode,latitude:null,longitude:null,device_info:'employee_pwa_'+(navigator.platform||'browser')})});const data=await res.json().catch(()=>({}));if(!res.ok||!data.success)throw new Error(data.message||'Wajah belum cocok.');setStatus('Presensi berhasil dicatat.');if(stream)stream.getTracks().forEach(t=>t.stop());setTimeout(()=>location.assign(redirectUrl),600)}catch(e){setStatus(e.message||'Scan gagal. Silakan ulangi.');button.disabled=false;busy=false}}button.addEventListener('click',scan);window.addEventListener('pagehide',()=>stream&&stream.getTracks().forEach(t=>t.stop()));init()})();
</script>
